// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;

import java.lang.reflect.Field;
import java.nio.file.Path;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The learned-state maintenance that runs after a commit (filter selectivity reset, operator feedback decay, frontier
 * bookkeeping) is advisory. Once the triple and value stores have committed, the data is durable: a failure in one of
 * those hooks must neither roll back nor fail the commit (the caller would retry and duplicate the write) and must not
 * stop the store. The failing service instead degrades toward "no evidence" (review finding 3.7.5 (b)).
 * <p>
 * The operator feedback failure is injected through {@link LmdbOperatorFeedbackStats#setLearnedStateObserver}, never
 * through a Mockito spy: spying the stats class retransforms it for the whole test JVM, after which every later runtime
 * feedback publication allocates (LmdbRuntimeFeedbackTargetTest asserts that publication allocates nothing).
 */
class LmdbPostCommitLearnedStateFailureTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:test:post-commit:p");

	@Test
	void failingOperatorFeedbackHookMustNotRollBackOrFailTheDurableCommit(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		store.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			LmdbOperatorFeedbackStats operatorStats = field(backingStore, "operatorFeedbackStats",
					LmdbOperatorFeedbackStats.class);
			assertNotNull(operatorStats, "precondition: learned services are enabled for this store");
			AtomicInteger resets = new AtomicInteger();
			operatorStats.setLearnedStateObserver(new LmdbOperatorFeedbackStats.LearnedStateObserver() {
				@Override
				public void storeMutationRecorded(long committedStatementMutationStamp, Set<Long> predicateIds,
						LmdbOperatorFeedbackStats.MutationExtent extent) {
					throw new IllegalStateException("injected post-commit learned-state failure");
				}

				@Override
				public void learnedStateReset() {
					resets.incrementAndGet();
				}
			});

			assertDoesNotThrow(() -> addStatement(store, "first"),
					"a failure in advisory post-commit learned-state maintenance must not fail the durable commit");
			assertEquals(1L, size(store), "the committed statement must be visible to a new connection");
			assertEquals(1, resets.get(), "the failing operator feedback service must be reset to no evidence");

			assertDoesNotThrow(() -> addStatement(store, "second"), "the store must stay writable afterwards");
			assertEquals(2L, size(store), "later commits must land normally");
		} finally {
			store.shutDown();
		}
	}

	@Test
	void failingFilterSelectivityHookMustNotRollBackOrFailTheDurableCommit(@TempDir Path dataDir) throws Exception {
		LmdbStore store = newStore(dataDir);
		store.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			LmdbFilterSelectivityStats real = field(backingStore, "filterSelectivityStats",
					LmdbFilterSelectivityStats.class);
			assertNotNull(real, "precondition: learned services are enabled for this store");
			LmdbFilterSelectivityStats failing = spy(real);
			doThrow(new IllegalStateException("injected post-commit learned-state failure"))
					.when(failing)
					.recordStoreMutation(anyLong());
			setField(backingStore, "filterSelectivityStats", failing);

			assertDoesNotThrow(() -> addStatement(store, "first"),
					"a failure in advisory post-commit learned-state maintenance must not fail the durable commit");
			assertEquals(1L, size(store), "the committed statement must be visible to a new connection");
			verify(failing).reset();

			assertDoesNotThrow(() -> addStatement(store, "second"), "the store must stay writable afterwards");
			assertEquals(2L, size(store), "later commits must land normally");
		} finally {
			store.shutDown();
		}
	}

	private static LmdbStore newStore(Path dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(1024L * 1024L);
		return new LmdbStore(dataDir.toFile(), config);
	}

	private static void addStatement(LmdbStore store, String suffix) {
		try (SailConnection connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(VF.createIRI("urn:test:post-commit:s:" + suffix), PREDICATE,
					VF.createLiteral(suffix));
			connection.commit();
		}
	}

	private static long size(LmdbStore store) {
		try (SailConnection connection = store.getConnection()) {
			return connection.size();
		}
	}

	private static <T> T field(Object target, String name, Class<T> type) throws Exception {
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return type.cast(field.get(target));
	}

	private static void setField(Object target, String name, Object value) throws Exception {
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}
}
